-- bm Font: Advanced font editor for BareMetal (640x360)
-- Create, edit, and organize bitmap fonts with dropdown library & scale selection.

local HEX_ORIG_8X16 = ""
local HEX_INTER_8X16 = ""
local HEX_6X12 = ""

local C = {
  bg = 0x0E131C,
  panel = 0x151D2A,
  panel_hi = 0x1D283A,
  border = 0x26354C,
  border_hi = 0x00AAB0,
  cyan = 0x00D0D8,
  cyan_dim = 0x007880,
  yellow = 0xFFCC00,
  white = 0xFFFFFF,
  dim = 0x788CA4,
  px_on = 0x00E5FF,
  px_off = 0x1A2332,
  grid = 0x222E42,
  btn = 0x1F2B3E,
  btn_hi = 0x2A3B56,
  btn_text = 0xD8E4F2,
  good = 0x50E0B0,
  warn = 0xFFA040,
  red = 0xFF5555,
  modal_bg = 0x101722,
}

local function decode_hex(hex, h)
  local t = {}
  for i = 0, 255 do
    local g = {}
    local off = i * h * 2
    for r = 1, h do
      local b = tonumber(hex:sub(off + (r-1)*2 + 1, off + r*2), 16) or 0
      g[r] = b
    end
    t[i] = g
  end
  return t
end

-- Font Library
local fonts = {
  { id = "orig_8x16", name = "Orig 8x16", cw = 8, ch = 16, glyphs = decode_hex(HEX_ORIG_8X16, 16) },
  { id = "inter_8x16", name = "Inter 8x16", cw = 8, ch = 16, glyphs = decode_hex(HEX_INTER_8X16, 16) },
  { id = "6x12", name = "6x12", cw = 6, ch = 12, glyphs = decode_hex(HEX_6X12, 12) },
}

local active_font_idx = 2
local cur_font = fonts[active_font_idx]
local cw, ch = cur_font.cw, cur_font.ch
local glyphs = cur_font.glyphs

local function select_font(idx)
  if idx < 1 or idx > #fonts then return end
  active_font_idx = idx
  cur_font = fonts[idx]
  cw, ch = cur_font.cw, cur_font.ch
  glyphs = cur_font.glyphs
end

local cur_char = 65 -- 'A'
local cur_px, cur_py = 0, 0
local clipboard = nil
local notice = "bm Font ready"
local notice_timer = 120

-- UI State
local preview_scale = 1 -- 1, 2, or 3
local dropdown_open = false
local new_modal_open = false
local new_font_size = "8x16"
local new_font_base = "inter"

local function set_notice(msg)
  notice = msg
  notice_timer = 140
end

local function get_pixel(char_idx, x, y)
  local g = glyphs[char_idx]
  if not g or y < 0 or y >= ch or x < 0 or x >= cw then return 0 end
  local row = g[y + 1] or 0
  local bit = cw - 1 - x
  return (row >> bit) & 1
end

local function set_pixel(char_idx, x, y, val)
  local g = glyphs[char_idx]
  if not g or y < 0 or y >= ch or x < 0 or x >= cw then return end
  local bit = cw - 1 - x
  local row = g[y + 1] or 0
  if val == 1 then
    row = row | (1 << bit)
  else
    row = row & ~(1 << bit)
  end
  g[y + 1] = row
end

local function toggle_pixel(char_idx, x, y)
  local val = get_pixel(char_idx, x, y)
  set_pixel(char_idx, x, y, 1 - val)
end

local function clear_glyph()
  local g = glyphs[cur_char]
  for y = 1, ch do g[y] = 0 end
  set_notice("Cleared glyph")
end

local function invert_glyph()
  local mask = (1 << cw) - 1
  local g = glyphs[cur_char]
  for y = 1, ch do g[y] = (g[y] or 0) ~ mask end
  set_notice("Inverted glyph")
end

local function shift_glyph(dx, dy)
  local g = glyphs[cur_char]
  local mask = (1 << cw) - 1
  if dy ~= 0 then
    if dy > 0 then
      for y = ch, 2, -1 do g[y] = g[y - 1] end
      g[1] = 0
    else
      for y = 1, ch - 1 do g[y] = g[y + 1] end
      g[ch] = 0
    end
  end
  if dx ~= 0 then
    for y = 1, ch do
      local row = g[y] or 0
      if dx > 0 then row = (row >> 1) & mask
      else row = (row << 1) & mask end
      g[y] = row
    end
  end
  set_notice("Shifted glyph")
end

local function flip_h()
  local g = glyphs[cur_char]
  for y = 1, ch do
    local row = g[y] or 0
    local new_row = 0
    for x = 0, cw - 1 do
      local bit = (row >> (cw - 1 - x)) & 1
      new_row = new_row | (bit << x)
    end
    g[y] = new_row
  end
  set_notice("Flipped H")
end

local function flip_v()
  local g = glyphs[cur_char]
  local copy = {}
  for y = 1, ch do copy[y] = g[y] end
  for y = 1, ch do g[y] = copy[ch - y + 1] end
  set_notice("Flipped V")
end

local function copy_glyph()
  clipboard = {}
  local g = glyphs[cur_char]
  for y = 1, ch do clipboard[y] = g[y] end
  set_notice("Copied glyph")
end

local function paste_glyph()
  if not clipboard then
    set_notice("Clipboard empty")
    return
  end
  local g = glyphs[cur_char]
  for y = 1, ch do g[y] = clipboard[y] or 0 end
  set_notice("Pasted glyph")
end

local function reset_glyph()
  local def = nil
  if cur_font.id == "orig_8x16" then def = decode_hex(HEX_ORIG_8X16, 16)[cur_char]
  elseif cur_font.id == "6x12" then def = decode_hex(HEX_6X12, 12)[cur_char]
  else def = decode_hex(HEX_INTER_8X16, 16)[cur_char] end
  if def then
    local g = glyphs[cur_char]
    for y = 1, ch do g[y] = def[y] or 0 end
    set_notice("Reset glyph to default")
  end
end

local function save_font()
  save({ active_idx = active_font_idx, fonts = fonts })
  set_notice("Saved font library to SD card!")
end

local function export_font()
  save({ active_idx = active_font_idx, fonts = fonts })
  -- Also write .bmf document if doc_write is available
  local fname = (cur_font.name:gsub("%s+", "_"):lower():sub(1, 8)) .. ".bmf"
  local hex_out = {}
  for i = 0, 255 do
    local g = cur_font.glyphs[i] or {}
    for y = 1, cur_font.ch do
      local b = g[y] or 0
      table.insert(hex_out, string.format("%02X", b))
    end
  end
  local payload = string.format("BMF1\nname=%s\nw=%d\nh=%d\ndata=%s\n", cur_font.name, cur_font.cw, cur_font.ch, table.concat(hex_out))
  if doc_write then
    local ok, err = doc_write(fname, payload)
    if ok then
      set_notice("Exported /docs/" .. fname .. " & saved SD!")
      return
    end
  end
  set_notice("Saved to SD card (/bm/save)!")
end

local function create_new_font()
  local ncw, nch = 8, 16
  if new_font_size == "8x8" then ncw, nch = 8, 8
  elseif new_font_size == "6x12" then ncw, nch = 6, 12 end

  local base_glyphs = nil
  if new_font_base == "inter" then base_glyphs = decode_hex(HEX_INTER_8X16, 16)
  elseif new_font_base == "orig" then base_glyphs = decode_hex(HEX_ORIG_8X16, 16) end

  local ng = {}
  for i = 0, 255 do
    local g = {}
    for y = 1, nch do
      if base_glyphs and base_glyphs[i] and base_glyphs[i][y] and nch == 16 then
        g[y] = base_glyphs[i][y]
      else
        g[y] = 0
      end
    end
    ng[i] = g
  end

  local new_name = "Font " .. (#fonts + 1)
  local new_entry = {
    id = "custom_" .. (#fonts + 1),
    name = new_name,
    cw = ncw,
    ch = nch,
    glyphs = ng
  }
  table.insert(fonts, new_entry)
  select_font(#fonts)
  new_modal_open = false
  save_font()
  set_notice("Created " .. new_name)
end

-- Layout positions
local CANVAS_X, CANVAS_Y = 28, 44
local CANVAS_SCALE = 15

local CMAP_X, CMAP_Y = 180, 44
local CMAP_CW, CMAP_CH = 15, 16

local PREV_X, PREV_Y = 444, 210
local PREV_W, PREV_H = 176, 100

-- Main Tool Buttons
local buttons = {
  { id = "clr", x = 444, y = 100, w = 40, h = 20, label = "Clear", fn = clear_glyph },
  { id = "inv", x = 488, y = 100, w = 40, h = 20, label = "Invert", fn = invert_glyph },
  { id = "fliph", x = 532, y = 100, w = 42, h = 20, label = "FlipH", fn = flip_h },
  { id = "flipv", x = 578, y = 100, w = 42, h = 20, label = "FlipV", fn = flip_v },
  
  { id = "up", x = 472, y = 126, w = 26, h = 18, label = "^", fn = function() shift_glyph(0, -1) end },
  { id = "down", x = 472, y = 148, w = 26, h = 18, label = "v", fn = function() shift_glyph(0, 1) end },
  { id = "left", x = 444, y = 137, w = 26, h = 18, label = "<", fn = function() shift_glyph(-1, 0) end },
  { id = "right", x = 500, y = 137, w = 26, h = 18, label = ">", fn = function() shift_glyph(1, 0) end },
  
  { id = "copy", x = 536, y = 130, w = 40, h = 20, label = "Copy", fn = copy_glyph },
  { id = "paste", x = 580, y = 130, w = 40, h = 20, label = "Paste", fn = paste_glyph },
  
  { id = "reset", x = 444, y = 174, w = 84, h = 22, label = "Reset", fn = reset_glyph },
  { id = "save", x = 536, y = 174, w = 84, h = 22, label = "Save / Export", fn = export_font },
}

-- Interactive Scale Buttons
local scale_btns = {
  { scale = 1, x = 520, y = 40, w = 26, h = 16, label = "1x" },
  { scale = 2, x = 550, y = 40, w = 26, h = 16, label = "2x" },
  { scale = 3, x = 580, y = 40, w = 26, h = 16, label = "3x" },
}

function _init()
  mouse(true)
  local data = saved()
  if data and data.fonts and #data.fonts > 0 then
    fonts = data.fonts
    if data.active_idx and fonts[data.active_idx] then
      select_font(data.active_idx)
    else
      select_font(1)
    end
    set_notice("Loaded font library from SD")
  end
end

function _update()
  if notice_timer > 0 then notice_timer = notice_timer - 1 end
  
  local mx, my, mb = mouse()
  local click = mx and mousep(0)
  
  -- Handle "Nuovo Font" Modal clicks
  if new_modal_open then
    if click then
      -- Size buttons
      if mx >= 220 and mx <= 260 and my >= 110 and my <= 128 then new_font_size = "8x16"
      elseif mx >= 270 and mx <= 310 and my >= 110 and my <= 128 then new_font_size = "8x8"
      elseif mx >= 320 and mx <= 360 and my >= 110 and my <= 128 then new_font_size = "6x12"
      -- Base buttons
      elseif mx >= 220 and mx <= 270 and my >= 150 and my <= 168 then new_font_base = "blank"
      elseif mx >= 280 and mx <= 340 and my >= 150 and my <= 168 then new_font_base = "inter"
      elseif mx >= 350 and mx <= 410 and my >= 150 and my <= 168 then new_font_base = "orig"
      -- Create button
      elseif mx >= 220 and mx <= 300 and my >= 195 and my <= 218 then
        create_new_font()
      -- Cancel button
      elseif mx >= 320 and mx <= 400 and my >= 195 and my <= 218 then
        new_modal_open = false
      -- Click outside modal closes it
      elseif mx < 180 or mx > 460 or my < 70 or my > 240 then
        new_modal_open = false
      end
    end
    return
  end
  
  -- Handle Dropdown menu clicks
  if dropdown_open then
    if click then
      local dy0 = 30
      local item_h = 20
      local handled = false
      for idx, f in ipairs(fonts) do
        local iy = dy0 + (idx - 1) * item_h
        if mx >= 14 and mx <= 200 and my >= iy and my < iy + item_h then
          select_font(idx)
          dropdown_open = false
          set_notice("Selected " .. f.name)
          handled = true
          break
        end
      end
      if not handled then
        local action_y = dy0 + #fonts * item_h + 6
        -- Click on "+ Nuovo Font..."
        if mx >= 14 and mx <= 200 and my >= action_y and my < action_y + item_h then
          dropdown_open = false
          new_modal_open = true
          handled = true
        -- Click on "Esporta in /docs"
        elseif mx >= 14 and mx <= 200 and my >= action_y + item_h and my < action_y + item_h * 2 then
          dropdown_open = false
          export_font()
          handled = true
        else
          dropdown_open = false
        end
      end
    end
    return
  end
  
  -- Top Dropdown button click
  if click and mx >= 14 and mx <= 180 and my >= 4 and my <= 24 then
    dropdown_open = true
    return
  end
  
  -- Interactive Scale buttons click
  if click then
    for _, sb in ipairs(scale_btns) do
      if mx >= sb.x and mx < sb.x + sb.w and my >= sb.y and my < sb.y + sb.h then
        preview_scale = sb.scale
        set_notice("Preview Scale: " .. preview_scale .. "x")
        return
      end
    end
  end
  
  -- Tool Button clicks
  if click then
    for _, btn in ipairs(buttons) do
      if mx >= btn.x and mx < btn.x + btn.w and my >= btn.y and my < btn.y + btn.h then
        btn.fn()
        return
      end
    end
  end
  
  -- Character map selection
  if mx and (mousep(0) or (mb and mb & 1 ~= 0)) then
    if mx >= CMAP_X and mx < CMAP_X + 16 * CMAP_CW and my >= CMAP_Y and my < CMAP_Y + 16 * CMAP_CH then
      local col = (mx - CMAP_X) // CMAP_CW
      local row = (my - CMAP_Y) // CMAP_CH
      local idx = row * 16 + col
      if idx >= 0 and idx <= 255 then
        cur_char = idx
      end
    end
  end
  
  -- Pixel Canvas editing
  local grid_w = cw * CANVAS_SCALE
  local grid_h = ch * CANVAS_SCALE
  if mx and mx >= CANVAS_X and mx < CANVAS_X + grid_w and my >= CANVAS_Y and my < CANVAS_Y + grid_h then
    local px = (mx - CANVAS_X) // CANVAS_SCALE
    local py = (my - CANVAS_Y) // CANVAS_SCALE
    if px >= 0 and px < cw and py >= 0 and py < ch then
      cur_px, cur_py = px, py
      if mb and (mb & 1 ~= 0) then
        set_pixel(cur_char, px, py, 1)
      elseif mb and (mb & 2 ~= 0) then
        set_pixel(cur_char, px, py, 0)
      end
    end
  end
  
  -- D-pad / Keyboard Navigation
  if btnp(0) then
    if cur_px > 0 then cur_px = cur_px - 1 else cur_char = (cur_char - 1) % 256 end
  elseif btnp(1) then
    if cur_px < cw - 1 then cur_px = cur_px + 1 else cur_char = (cur_char + 1) % 256 end
  elseif btnp(2) then
    if cur_py > 0 then cur_py = cur_py - 1 else cur_char = (cur_char - 16) % 256 end
  elseif btnp(3) then
    if cur_py < ch - 1 then cur_py = cur_py + 1 else cur_char = (cur_char + 16) % 256 end
  end
  
  if btnp(4) then -- A / Space
    toggle_pixel(cur_char, cur_px, cur_py)
  elseif btnp(5) then -- B / X
    set_pixel(cur_char, cur_px, cur_py, 0)
  end
  
  -- Typed keys
  local k = keyp()
  while k do
    if k == "\t" then
      dropdown_open = not dropdown_open
    elseif k == "^s" or k == "ctrl s" then
      export_font()
    elseif k == "^c" or k == "ctrl c" then
      copy_glyph()
    elseif k == "^v" or k == "ctrl v" then
      paste_glyph()
    elseif k == "c" then
      clear_glyph()
    elseif k == "i" then
      invert_glyph()
    elseif k == "1" then
      preview_scale = 1
      set_notice("Scale 1x")
    elseif k == "2" then
      preview_scale = 2
      set_notice("Scale 2x")
    elseif k == "3" then
      preview_scale = 3
      set_notice("Scale 3x")
    elseif #k == 1 and k:byte() >= 32 and k:byte() <= 126 then
      cur_char = k:byte()
    end
    k = keyp()
  end
end

local function draw_custom_glyph(char_idx, gx, gy, scale, col)
  local g = glyphs[char_idx]
  if not g then return end
  for y = 0, ch - 1 do
    local row = g[y + 1] or 0
    for x = 0, cw - 1 do
      local bit = (row >> (cw - 1 - x)) & 1
      if bit == 1 then
        if scale == 1 then
          pset(gx + x, gy + y, col)
        else
          rectfill(gx + x * scale, gy + y * scale, scale, scale, col)
        end
      end
    end
  end
end

function _draw()
  cls(C.bg)
  font("8x16")
  
  -- Header
  rectfill(0, 0, 640, 28, C.panel)
  line(0, 28, 639, 28, C.border)
  
  -- Dropdown Menu Button
  rectfill(14, 4, 166, 20, dropdown_open and C.btn_hi or C.btn)
  rect(14, 4, 166, 20, dropdown_open and C.cyan or C.border)
  print("Font: " .. cur_font.name .. "  v", 20, 6, dropdown_open and C.cyan or C.btn_text)
  
  -- Glyph info
  local char_rep = (cur_char >= 32 and cur_char <= 126) and string.char(cur_char) or "?"
  local info_str = string.format("Glyph: '%s'  Dec: %d  Hex: 0x%02X", char_rep, cur_char, cur_char)
  print(info_str, 200, 6, C.white)
  
  if notice_timer > 0 then
    print(notice, 440, 6, C.good)
  end
  
  -- Canvas
  local grid_w = cw * CANVAS_SCALE
  local grid_h = ch * CANVAS_SCALE
  rectfill(CANVAS_X - 6, CANVAS_Y - 6, grid_w + 12, grid_h + 12, C.panel)
  rect(CANVAS_X - 6, CANVAS_Y - 6, grid_w + 12, grid_h + 12, C.border)
  
  for y = 0, ch - 1 do
    for x = 0, cw - 1 do
      local on = get_pixel(cur_char, x, y)
      local rx = CANVAS_X + x * CANVAS_SCALE
      local ry = CANVAS_Y + y * CANVAS_SCALE
      rectfill(rx, ry, CANVAS_SCALE - 1, CANVAS_SCALE - 1, on == 1 and C.px_on or C.px_off)
    end
  end
  
  -- Baseline guide
  local base_y = (ch == 16) and 13 or (ch == 8 and 7 or 10)
  line(CANVAS_X, CANVAS_Y + base_y * CANVAS_SCALE, CANVAS_X + grid_w - 1, CANVAS_Y + base_y * CANVAS_SCALE, C.warn)
  
  -- Cursor
  local cx = CANVAS_X + cur_px * CANVAS_SCALE
  local cy = CANVAS_Y + cur_py * CANVAS_SCALE
  rect(cx - 1, cy - 1, CANVAS_SCALE + 1, CANVAS_SCALE + 1, C.yellow)
  rect(cx - 2, cy - 2, CANVAS_SCALE + 3, CANVAS_SCALE + 3, C.yellow)
  
  -- Character Map (16x16)
  rectfill(CMAP_X - 6, CMAP_Y - 6, 16 * CMAP_CW + 12, 16 * CMAP_CH + 12, C.panel)
  rect(CMAP_X - 6, CMAP_Y - 6, 16 * CMAP_CW + 12, 16 * CMAP_CH + 12, C.border)
  
  for row = 0, 15 do
    for col = 0, 15 do
      local idx = row * 16 + col
      local rx = CMAP_X + col * CMAP_CW
      local ry = CMAP_Y + row * CMAP_CH
      
      if idx == cur_char then
        rectfill(rx, ry, CMAP_CW, CMAP_CH, C.panel_hi)
        rect(rx, ry, CMAP_CW, CMAP_CH, C.yellow)
      end
      
      local off_x = (CMAP_CW - cw) // 2
      local off_y = (CMAP_CH - ch) // 2
      draw_custom_glyph(idx, rx + off_x, ry + off_y, 1, idx == cur_char and C.yellow or C.dim)
    end
  end
  
  -- Toolbox & Actual Size
  rectfill(438, CANVAS_Y - 6, 192, 160, C.panel)
  rect(438, CANVAS_Y - 6, 192, 160, C.border)
  
  -- Scale Section with clickable buttons
  print("Scale:", 444, 40, C.dim)
  for _, sb in ipairs(scale_btns) do
    local is_sel = (preview_scale == sb.scale)
    rectfill(sb.x, sb.y, sb.w, sb.h, is_sel and C.cyan or C.btn)
    rect(sb.x, sb.y, sb.w, sb.h, is_sel and C.white or C.border)
    print(sb.label, sb.x + 5, sb.y + 1, is_sel and C.bg or C.btn_text)
  end
  
  -- Sample glyphs (highlight active scale)
  draw_custom_glyph(cur_char, 444, 64, 1, (preview_scale == 1) and C.cyan or C.white)
  draw_custom_glyph(cur_char, 464, 60, 2, (preview_scale == 2) and C.cyan or C.white)
  draw_custom_glyph(cur_char, 492, 56, 3, (preview_scale == 3) and C.cyan or C.white)
  
  font("6x12")
  for _, btn in ipairs(buttons) do
    rectfill(btn.x, btn.y, btn.w, btn.h, C.btn)
    rect(btn.x, btn.y, btn.w, btn.h, C.border)
    print(btn.label, btn.x + 4, btn.y + 4, C.btn_text)
  end
  font("8x16")
  
  -- Live Preview Panel
  rectfill(PREV_X - 6, PREV_Y - 6, PREV_W + 12, PREV_H + 12, C.panel)
  rect(PREV_X - 6, PREV_Y - 6, PREV_W + 12, PREV_H + 12, C.border)
  
  print(string.format("Live Preview (%dx):", preview_scale), PREV_X, PREV_Y - 2, C.dim)
  
  local preview_lines = {
    "The quick fox",
    "jumps over lazy",
    "0123456789",
    "Hello BareMetal!",
  }
  
  local p_scale = preview_scale
  local line_h = (ch * p_scale) + 2
  for line_i, line_str in ipairs(preview_lines) do
    local ly = PREV_Y + 16 + (line_i - 1) * line_h
    if ly + line_h <= PREV_Y + PREV_H then
      local lx = PREV_X
      for ci = 1, #line_str do
        if lx + cw * p_scale > PREV_X + PREV_W then break end
        local b = line_str:byte(ci)
        draw_custom_glyph(b, lx, ly, p_scale, (line_i == 4) and C.cyan or C.white)
        lx = lx + cw * p_scale
      end
    end
  end
  
  -- Dropdown Menu Overlay
  if dropdown_open then
    local dy0 = 26
    local dw = 190
    local item_h = 20
    local dh = #fonts * item_h + 54
    rectfill(14, dy0, dw, dh, C.panel_hi)
    rect(14, dy0, dw, dh, C.cyan)
    
    for idx, f in ipairs(fonts) do
      local iy = dy0 + (idx - 1) * item_h
      local is_cur = (idx == active_font_idx)
      if is_cur then
        rectfill(16, iy + 2, dw - 4, item_h - 2, C.btn_hi)
      end
      local mark = is_cur and "> " or "  "
      print(string.format("%s%s (%dx%d)", mark, f.name, f.cw, f.ch), 20, iy + 3, is_cur and C.cyan or C.btn_text)
    end
    
    -- Separator
    local sep_y = dy0 + #fonts * item_h + 2
    line(16, sep_y, 14 + dw - 2, sep_y, C.border)
    
    -- Actions
    local a1_y = sep_y + 4
    print("+ Nuovo Font...", 24, a1_y + 2, C.yellow)
    local a2_y = a1_y + item_h
    print("v Esporta in /docs", 24, a2_y + 2, C.good)
  end
  
  -- Modal Dialog "Nuovo Font" Overlay
  if new_modal_open then
    -- Dim background
    rectfill(170, 70, 300, 190, C.modal_bg)
    rect(170, 70, 300, 190, C.cyan)
    
    print("Crea Nuovo Font", 245, 80, C.white)
    line(180, 98, 460, 98, C.border)
    
    print("Dimensioni:", 185, 110, C.dim)
    for _, opt in ipairs({ {"8x16", 280}, {"8x8", 340}, {"6x12", 400} }) do
      for _, sz in ipairs(opt) do
        local sel = (new_font_size == sz[1])
        rectfill(sz[2], 108, 48, 18, sel and C.cyan or C.btn)
        rect(sz[2], 108, 48, 18, sel and C.white or C.border)
        print(sz[1], sz[2] + 6, 110, sel and C.bg or C.btn_text)
      end
    end
    
    print("Base:", 185, 145, C.dim)
    for _, base in ipairs({ {"blank", "Vuoto", 240}, {"inter", "Inter", 310}, {"orig", "Terminus", 380} }) do
      for _, b in ipairs(base) do
        local sel = (new_font_base == b[1])
        rectfill(b[3], 143, 62, 18, sel and C.cyan or C.btn)
        rect(b[3], 143, 62, 18, sel and C.white or C.border)
        print(b[2], b[3] + 6, 145, sel and C.bg or C.btn_text)
      end
    end
    
    -- Action buttons
    rectfill(210, 205, 90, 26, C.good)
    print("Crea", 238, 210, C.bg)
    
    rectfill(340, 205, 90, 26, C.btn)
    rect(340, 205, 90, 26, C.border)
    print("Annulla", 355, 210, C.btn_text)
  end
  
  -- Bottom Bar
  rectfill(0, 336, 640, 24, C.panel)
  line(0, 336, 639, 336, C.border)
  font("8x16")
  print("[Mouse/D-pad] Edit  [Space/A] Draw  [Scale 1/2/3] Zoom  [Ctrl+S] Save", 12, 340, C.dim)
end
